    return vector


def center_scale(vectors):
    center=[st.median(v[j] for v in vectors) for j in range(len(FEATURE_NAMES))]
    scale=[max(FLOORS[j],1.4826*st.median(abs(v[j]-center[j]) for v in vectors)) for j in range(len(center))]
    return center,scale


