## `test/disclosure.test.ts`

```ts
// Guards for the disclosure bracket (issue #31).
//
// The three mutations these tests exist to kill:
//   1. treating the straddle as on-time (trusting the subject);
//   2. deciding the never-disclosed case on the reader's clock T instead of
//      the chain evidence's own time (accusing on stale evidence);
//   3. honoring claimed_at (letting testimony decide).

import test from "node:test";
import assert from "node:assert/strict";
import { decideDisclosure } from "../src/disclosure.ts";

const HOUR = 3_600_000;
const OUT = 1_700_000_000_000; // the outflow
const MS = 6 * HOUR; // the subject had six hours
const D = OUT + MS; // the deadline

test("a disclosure seen at the deadline exactly is in time", () => {
  const r = decideDisclosure({ absent_at: OUT, present_at: D }, OUT, MS, D, D);
  assert.equal(r.status, "IN_TIME");
});

test("absent at the deadline, present after: provably late", () => {
  const r = decideDisclosure({ absent_at: D, present_at: D + HOUR }, OUT, MS, D + HOUR, D + HOUR);
  assert.equal(r.status, "LATE");
});

test("a bracket straddling the deadline is UNDECIDABLE, with the gap published", () => {
  // Killing mutation #1: treat the straddle as on-time. The arrival fell into
  // two unobserved hours; calling it in time takes the subject's word for it.
  const r = decideDisclosure({ absent_at: D - HOUR, present_at: D + HOUR }, OUT, MS, D + HOUR, D + HOUR);
  assert.equal(r.status, "UNDECIDABLE");
  assert.equal(r.status === "UNDECIDABLE" ? r.gap_ms : null, 2 * HOUR);
});

test("no absent row and first seen late is UNDECIDABLE, not late", () => {
  // Nothing proves it was absent at the deadline; nothing proves it was there.
  const r = decideDisclosure({ absent_at: null, present_at: D + HOUR }, OUT, MS, D + HOUR, D + HOUR);
  assert.equal(r.status, "UNDECIDABLE");
});

test("no absent row but first seen in time is in time", () => {
  const r = decideDisclosure({ absent_at: null, present_at: D - HOUR }, OUT, MS, D, D);
  assert.equal(r.status, "IN_TIME");
});

test("claimed_at in time does not rescue a provably late bracket", () => {
  // Killing mutation #3, direction one: the subject claims it disclosed an
  // hour after the outflow; the chained readings show it absent at the
  // deadline. The claim is testimony and must not decide.
  const r = decideDisclosure(
    { absent_at: D, present_at: D + HOUR, claimed_at: OUT + HOUR },
    OUT,
    MS,
    D + HOUR,
    D + HOUR,
  );
  assert.equal(r.status, "LATE");
});

test("claimed_at late does not poison a provably in-time bracket", () => {
  // Killing mutation #3, direction two: same rule, protecting the subject.
  const r = decideDisclosure(
    { absent_at: OUT, present_at: D - HOUR, claimed_at: D + HOUR },
    OUT,
    MS,
    D,
    D,
  );
  assert.equal(r.status, "IN_TIME");
});

test("never disclosed, with a chain reading past the deadline: NEVER", () => {
  const r = decideDisclosure(undefined, OUT, MS, D + 1, D + 1);
  assert.equal(r.status, "NEVER");
});

test("never disclosed, deadline passed at T, but the evidence is stale: UNDECIDABLE", () => {
  // Killing mutation #2: decide on T. The reader's clock is past the deadline
  // but the snapshot was taken an hour before it. That snapshot is silent
  // about everything after itself; DEFAULTED on it is a false accusation.
  const r = decideDisclosure(undefined, OUT, MS, D - HOUR, D + HOUR);
  assert.equal(r.status, "UNDECIDABLE");
});

test("never disclosed, deadline not yet passed: PENDING", () => {
  const r = decideDisclosure(undefined, OUT, MS, OUT + HOUR, OUT + HOUR);
  assert.equal(r.status, "PENDING");
});

test("an inverted bracket decides nothing", () => {
  // A reading WITHOUT the disclosure dated after a reading WITH it is not a
  // bracket, it is an inconsistency. Refuse to decide on it either way.
  const r = decideDisclosure({ absent_at: D + HOUR, present_at: D - HOUR }, OUT, MS, D + HOUR, D + HOUR);
  assert.equal(r.status, "UNDECIDABLE");
  assert.match(r.status === "UNDECIDABLE" ? r.reason : "", /inconsistent/);
});
```

