# SPDX-License-Identifier: MIT
"""Offline behavioral-signal experiment. See README.md for the event format."""

import argparse
import hashlib
import json
import math
from pathlib import Path
from statistics import median


FEATURES = {
    "bend": 0.025,
    "initial_pace": 0.035,
    "path_excess": 0.025,
    "click_gap_shape": 0.09,
    "text_gap_shape": 0.10,
    "correction_share": 0.025,
    "batch_shape": 0.12,
}
THRESHOLD = 2.8
SCHEMA = "marrow-shape-profile-1"
TEXT_SOURCES = {"typed", "onscreen", "inserted"}


class InsufficientEvidence(ValueError):
    """The recording cannot support a score."""


def valid_coordinate(value):
    return type(value) in (int, float) and 0 <= value <= 1


def read_events(path):
    events = []
    previous = -1
    with Path(path).open(encoding="utf-8") as stream:
        for line_number, line in enumerate(stream, 1):
            try:
                item = json.loads(line)
                t, kind = item["t"], item["kind"]
                if type(t) is not int or t < 0 or t < previous:
                    raise ValueError("timestamps must be nonnegative and nondecreasing")
                if kind in ("move", "click"):
                    x, y = item["x"], item["y"]
                    if not valid_coordinate(x) or not valid_coordinate(y):
                        raise ValueError("invalid normalized coordinate")
                    events.append((t, kind, x, y))
                elif kind == "text":
                    source, op, count = item["source"], item["op"], item["n"]
                    if source not in TEXT_SOURCES or op not in ("insert", "delete"):
                        raise ValueError("invalid text source or operation")
                    if type(count) is not int or count < 1:
                        raise ValueError("text count must be a positive integer")
                    events.append((t, kind, source, op, count))
                else:
                    raise ValueError("unknown event kind")
                previous = t
            except (KeyError, TypeError, ValueError) as exc:
                raise ValueError(f"{path}:{line_number}: {exc}") from exc
    return events


def quantile(values, fraction):
    ordered = sorted(values)
    index = (len(ordered) - 1) * fraction
    lower = int(index)
    return ordered[lower] + (index - lower) * (ordered[math.ceil(index)] - ordered[lower])


def gap_shape(times):
    gaps = [right - left for left, right in zip(times, times[1:]) if right > left]
    if len(gaps) < 8:
        raise InsufficientEvidence("fewer than eight positive time gaps")
    return math.log(quantile(gaps, 0.8) / quantile(gaps, 0.2))


def stroke_shape(points):
    if len(points) < 6:
        return None
    start_t, _, start_x, start_y = points[0]
    end_t, _, end_x, end_y = points[-1]
    dx, dy = end_x - start_x, end_y - start_y
    chord = math.hypot(dx, dy)
    duration = end_t - start_t
    if chord < 0.025 or duration < 60:
        return None
    normalized = []
    for t, _, x, y in points:
        along = ((x - start_x) * dx + (y - start_y) * dy) / chord**2
        lateral = ((y - start_y) * dx - (x - start_x) * dy) / chord**2
        normalized.append(((t - start_t) / duration, along, lateral))
    for left, right in zip(normalized, normalized[1:]):
        if left[0] <= 0.5 < right[0]:
            fraction = (0.5 - left[0]) / (right[0] - left[0])
            initial_pace = left[1] + fraction * (right[1] - left[1])
            break
    path = sum(math.hypot(right[1] - left[1], right[2] - left[2])
               for left, right in zip(normalized, normalized[1:]))
    bend = quantile([abs(point[2]) for point in normalized], 0.8)
    return bend, initial_pace, path - 1


def extract(events):
    points, strokes, clicks, text = [], [], [], []
    for event in events:
        if event[1] == "text":
            text.append(event)
            continue
        if event[1] == "click":
            clicks.append(event[0])
            shape = stroke_shape([*points, event])
            if shape is not None:
                strokes.append(shape)
            points = []
        else:
            points.append(event)
    if len(strokes) < 8 or len(text) < 15:
        raise InsufficientEvidence("need eight click-ending strokes and fifteen text events")
    text_gaps, batch_shape = [], []
    for source in sorted({event[2] for event in text}):
        group = [event for event in text if event[2] == source]
        if len(group) >= 10:
            try:
                text_gaps.append(gap_shape([event[0] for event in group]))
            except InsufficientEvidence:
                continue
            counts = [event[4] for event in group if event[3] == "insert"]
            if counts:
                batch_shape.append(math.log(quantile(counts, 0.8) / quantile(counts, 0.2)))
    if not text_gaps or not batch_shape:
        raise InsufficientEvidence("need a text source with usable timing and insertion evidence")
    corrected = sum(event[4] for event in text if event[3] == "delete")
    total = sum(event[4] for event in text)
    return dict(zip(FEATURES, (
        *(median(values) for values in zip(*strokes)),
        gap_shape(clicks), median(text_gaps), corrected / total, median(batch_shape),
    )))


def fingerprint(events):
    offset = events[0][0]
    relative = [(event[0] - offset, *event[1:]) for event in events]
    return hashlib.sha256(json.dumps(relative, separators=(",", ":")).encode()).hexdigest()


def train(recordings):
    vectors, fingerprints = [], set()
    for events in recordings:
        vector = extract(events)
        digest = fingerprint(events)
        if digest not in fingerprints:
            vectors.append(vector)
            fingerprints.add(digest)
    if len(vectors) < 6:
        raise InsufficientEvidence("need six distinct usable enrollment sessions")
    centers = {key: median([row[key] for row in vectors]) for key in FEATURES}
    scales = {key: max(floor, 1.4826 * median([abs(row[key] - centers[key]) for row in vectors]))
              for key, floor in FEATURES.items()}
    return {"schema": SCHEMA, "center": centers, "scale": scales,
            "enrollment_hashes": sorted(fingerprints), "threshold": THRESHOLD}


