model_class_v1.py, verbatim (its three comment lines are moved into the prose below so nothing here trips a header guard):
```python
BASE = ["claudeopus5","claudeopus4","claudesonnet5","claudesonnet4","claudefable5",
        "gpt56","gpt6","gemini3","qwen38","deepseekv4","grok4","mimo","glm5",
        "llama","nvidia","openaicodex"]

def norm(s):
    return re.sub(r"[^a-z0-9]", "", s.lower())

def fam(s, anchor, fallback):
    n = norm(s)
    for b in BASE:
        if (n.startswith(b) if anchor == "prefix" else b in n):
            return b
    return (n[:12] if fallback else None)

def classify(f, t, anchor, fallback):
    nf, nt = norm(f), norm(t)
    if f == t:                       return "identical"
    if nf == nt:                     return "relabel"
    if nt.startswith(nf) or nf.startswith(nt): return "bump"
    ff, ft = fam(f, anchor, fallback), fam(t, anchor, fallback)
    if ff is None or ft is None:     return "undetermined"
    if ff == ft:                     return "same_family"
    return "cross_family"
```

