def validate_event(event, previous_time):
    if not isinstance(event, dict):
        raise RecordingError("expected a JSON object")
    time = event.get("t_ms")
    if type(time) is not int or time < previous_time or time > 86_400_000:
        raise RecordingError("timestamp must be a nondecreasing integer in [0, 86400000]")
    kind = event.get("type")
    if kind not in EVENT_TYPES:
        raise RecordingError("unknown event type")
    if kind in ("pointer", "click"):
        for name in ("x", "y"):
            coordinate = event.get(name)
            if type(coordinate) not in (float, int) or not 0 <= coordinate <= 1:
                raise RecordingError(f"coordinate {name} must be a finite number in [0, 1]")
    if kind == "text":
        if event.get("source") not in TEXT_SOURCES:
            raise RecordingError("text source must be typed, on_screen, or inserted")
        for name in ("inserted", "deleted"):
            if type(event.get(name)) is not int or not 0 <= event[name] <= 100_000:
                raise RecordingError(f"invalid text count: {name}")
        if event["inserted"] == event["deleted"] == 0:
            raise RecordingError("empty text operation")


def pointer_features(events):
    traces = []
    points = []
