        elif event["type"] == "click":
            if len(points) >= 5:
                traces.append((points, event["t_ms"]))
            points = []
    if len(traces) < 3:
        return {}

    measurements = defaultdict(list)
    for points, clicked_at in traces:
        xy = [(x, y) for x, y, _ in points]
        duration = max(1, points[-1][2] - points[0][2])
        segments = list(zip(xy, xy[1:], points, points[1:]))
        distances = [math.dist(start, end) for start, end, _, _ in segments]
        travel = sum(distances)
        displacement = math.dist(xy[0], xy[-1])
        if travel < 0.00001 or displacement < 0.00001:
            continue
        dx, dy = xy[-1][0] - xy[0][0], xy[-1][1] - xy[0][1]
        bend = max(abs(dx * (y - xy[0][1]) - dy * (x - xy[0][0])) for x, y in xy)
        velocities = [distance / max(1, end[2] - start[2]) for distance, (_, _, start, end) in zip(distances, segments)]
        early, late = velocities[:2], velocities[-2:]
        measurements["pointer_travel_per_gesture"].append(travel)
        measurements["pointer_efficiency"].append(displacement / travel)
        measurements["pointer_bend"].append(bend / displacement**2)
        measurements["pointer_late_speed"].append((median(late) + 1e-7) / (median(early) + 1e-7))
