def text_features(events):
    text = [event for event in events if event["type"] == "text"]
    if len(text) < 8:
        return None, {}
    source = Counter(event["source"] for event in text).most_common(1)[0][0]
    rates = [max(1, b["t_ms"] - a["t_ms"]) for a, b in zip(text, text[1:])]
    changes = [rate for rate, operation in zip(rates, text[1:]) if operation["deleted"]]
    rate = median(rates)
    metrics = {
        "text_burst_variation": median(abs(delta - rate) for delta in rates) / rate,
        "text_correction_fraction": sum(bool(event["deleted"]) for event in text) / len(text),
        "text_chunk_size": median(event["inserted"] for event in text if event["inserted"])
        if any(event["inserted"] for event in text) else 0,
    }
    if changes:
        metrics["text_correction_latency"] = median(changes) / rate
    return source, metrics


def features(events):
    source, text = text_features(events)
    return source, {**pointer_features(events), **text}


def enroll(recordings, threshold=DEFAULT_THRESHOLD):
    if not math.isfinite(threshold) or threshold <= 0:
        raise ValueError("threshold must be positive and finite")
    results = defaultdict(list)
    for recording in recordings:
        source, metrics = features(recording)
        if source and any(key.startswith("pointer_") for key in metrics):
            results[source].append(metrics)
    model = {}
    for source, results_by_recording in results.items():
