        model[source] = {}
        for name in FEATURE_FLOORS:
            values = [recording[name] for recording in results_by_recording if name in recording]
            if len(values) < 3:
                continue
            center = median(values)
            mad = median(abs(value - center) for value in values)
            model[source][name] = {"center": center, "scale": max(FEATURE_FLOORS[name], 1.4826 * mad)}
    if not model:
        raise RecordingError("enrollment needs at least three usable recordings of one input style")
    return {"schema": MODEL_SCHEMA, "threshold": threshold, "sources": model}


