```ts
    case "proof-after-close": {
      // POSTCLOSE, the read side. State is still a pure function of
      // (stored row, chain, T): the deadline comes from the row, the proof (or
      // its absence) from the chain, and whether the grace has run out from T.
      // No writer marks anything. A registry whose every writer died at
      // window close still reads DEFAULTED here the moment T passes the
      // deadline -- that is the silence case, and it must hold with no late
      // mark anywhere on disk.
      const deadline = c.window.to + p.grace_hours * 3_600_000;
      const proof = chain.disclosures?.[c.id];

      // A proof counts only when it is dated inside the grace: at or after the
      // close, at or before the deadline. A disclosure filed BEFORE the window
      // closed cannot attest to a window that had not finished happening, so it
      // does not count -- early is not a smaller kind of on-time.
      if (proof && proof.at_time >= c.window.to && proof.at_time <= deadline) {
        return { verdict: "HELD", reason: "closing proof filed within grace" };
      }

      if (T > deadline) {
        // Missing and late read the same verdict -- the proof was not
        // submitted on time, which is DEFAULTED and never BROKEN: this
        // predicate makes no claim about what the subject did inside the
        // window, only about whether they proved it afterwards. A late proof
        // is appended as evidence beside the default it did not prevent.
        if (proof && proof.at_time > deadline) {
          return {
            verdict: "DEFAULTED",
            reason: "closing proof arrived after the grace deadline",
            evidence: { commitment: c.id, proof_at: proof.at_time, deadline },
          };
        }
        if (proof) {
          // Dated before the close: it exists, but it is not a closing proof.
          return { verdict: "DEFAULTED", reason: "only proof under this id predates the window close" };
        }
        return { verdict: "DEFAULTED", reason: "no closing proof within grace" };
      }

      return {
        verdict: "HELD",
        reason: T >= c.window.to ? "grace running; no closing proof yet" : "window open; proof not yet due",
      };
    }
