```ts
// The monitoring layer: eyes that feed the lock, and a type system that keeps
// them from becoming the lock.
//
// The locked design (c60677, point 2): monitoring predicates are a separate
// layer that FEEDS the late-mark path; they never substitute for it. The named
// falsifier is a registry that "treats monitoring output as the late mark
// itself". This file is where that substitution is made unrepresentable:
//
//   - A monitoring predicate returns Observations. An Observation has no
//     verdict field, so there is no value a monitor can produce that type-checks
//     where a Verdict is required.
//   - `annotate` is the ONLY bridge between the two layers, and it returns the
//     evaluation's verdict, reason and evidence UNCHANGED, whatever the
//     observations say. A monitor that watched the proof arrive cannot lift a
//     DEFAULTED; a monitor that saw nothing cannot manufacture one.
//
// Why so strict: a monitor is a convenience reading of the same chain the
// evaluator reads. If its output could decide anything, registry correctness
// would depend on monitor uptime -- and the whole point of the read-path design
// (evaluate.ts) is that nothing a writer or watcher does or fails to do changes
// what a commitment's state IS, only how soon somebody notices.

import type { ChainState } from "./commitment.ts";
import type { Evaluation } from "./evaluate.ts";

/**
 * One thing a monitor noticed. Deliberately verdict-free: `note` is prose for
 * a reader, `tx` ties it to chain evidence when there is any, `at_time` dates
 * the sighting. Nothing here is machine-branchable as a state.
 */
export interface Observation {
  /** When the monitored condition was sighted, ms since epoch. */
  at_time: number;
  /** The transfer it refers to, when it refers to one. */
  tx?: string;
  /** What was seen, for a human. Never parsed. */
  note: string;
}

/**
 * The interface a monitoring library plugs into. Pure over the same inputs the
 * evaluator reads: same chain state in, observations out, no clock of its own
 * and nowhere to write. A library of human-pattern monitors (the #4782 offer)
 * implements this and nothing else.
 */
export interface MonitoringPredicate {
  /** Stable id, recorded beside any observation that gets logged. */
  id: string;
  observe(chain: ChainState): Observation[];
}

/** An evaluation with sightings attached beside it -- never inside it. */
export interface AnnotatedEvaluation extends Evaluation {
  observations: { monitor: string; observation: Observation }[];
}

/**
 * Attach what the monitors saw to what the evaluator decided. The verdict,
 * reason and evidence pass through untouched by construction: this function
 * does not read the observations before copying the evaluation, so there is no
 * code path on which they could matter. That is not an optimization, it is the
 * contract.
 */
export function annotate(
  evaluation: Evaluation,
  monitors: MonitoringPredicate[],
  chain: ChainState,
): AnnotatedEvaluation {
  const observations: AnnotatedEvaluation["observations"] = [];
  for (const m of monitors) {
    for (const observation of m.observe(chain)) {
      observations.push({ monitor: m.id, observation });
    }
  }
  return { ...evaluation, observations };
}
```

