```ts
// Part (c) of the acceptance specimen (c60677): the monitoring predicate
// interface, and the property that makes it safe to plug a library into --
// MONITORING OUTPUT IS NEVER THE LATE MARK. The locked falsifier names a
// registry that treats a monitor's sighting as the proof itself; these tests
// are written so that registry fails here.
//
// Killing mutations, each run before this was offered:
//   M5 annotate() lifts DEFAULTED to HELD when an observation claims the
//      proof was seen                                   -> 2 tests fail
//   M6 annotate() rewrites reason from a note           -> 2 tests fail

import test from "node:test";
import assert from "node:assert/strict";
import type { ChainState, Commitment } from "../src/commitment.ts";
import { evaluate } from "../src/evaluate.ts";
import { annotate, type MonitoringPredicate } from "../src/monitor.ts";

const SUBJ = "0x" + "aa".repeat(20);
const HOUR = 3_600_000;
const FROM = 1_000 * HOUR;
const TO = FROM + 24 * HOUR;
const DEADLINE = TO + 6 * HOUR;

const COMMITMENT: Commitment = {
  id: "pc-1",
  predicate: { kind: "proof-after-close", subject: SUBJ, token: null, grace_hours: 6 },
  window: { from: FROM, to: TO },
};

const SILENT_CHAIN: ChainState = {
  at_block: 10,
  at_time: DEADLINE + HOUR,
  transfers: [],
  balances: {},
  disclosures: {},
};

/** A monitor that insists it saw the proof. The chain carries none. */
const overeagerMonitor: MonitoringPredicate = {
  id: "overeager",
  observe: () => [{ at_time: TO + HOUR, note: "closing proof sighted (believe me)" }],
};

test("a monitor that claims the proof exists cannot lift the default", () => {
  const plain = evaluate(COMMITMENT, SILENT_CHAIN, DEADLINE + 1);
  assert.equal(plain.verdict, "DEFAULTED");
  const annotated = annotate(plain, [overeagerMonitor], SILENT_CHAIN);
  // The sighting is attached -- that is the monitor doing its one job --
  assert.equal(annotated.observations.length, 1);
  assert.equal(annotated.observations[0].monitor, "overeager");
  // -- and the verdict is exactly what the evaluator said. (M5 kills this.)
  assert.equal(annotated.verdict, "DEFAULTED");
  assert.equal(annotated.reason, plain.reason);
  assert.equal(annotated.evidence, plain.evidence);
});

test("annotate passes every verdict through unchanged, observations or none", () => {
  const held = evaluate(COMMITMENT, { ...SILENT_CHAIN, disclosures: { "pc-1": { at_time: TO + HOUR } } }, DEADLINE + 1);
  assert.equal(held.verdict, "HELD");
  for (const e of [held, evaluate(COMMITMENT, SILENT_CHAIN, DEADLINE + 1)]) {
    for (const monitors of [[], [overeagerMonitor]]) {
      const a = annotate(e, monitors, SILENT_CHAIN);
      assert.equal(a.verdict, e.verdict); // (M5)
      assert.equal(a.reason, e.reason); // (M6)
    }
  }
});

test("the interface is pure plumbing: observations are collected per monitor, in order", () => {
  const quiet: MonitoringPredicate = { id: "quiet", observe: () => [] };
  const twice: MonitoringPredicate = {
    id: "twice",
    observe: (chain) => [
      { at_time: chain.at_time, note: "first" },
      { at_time: chain.at_time, note: "second" },
    ],
  };
  const a = annotate(evaluate(COMMITMENT, SILENT_CHAIN, DEADLINE + 1), [quiet, twice], SILENT_CHAIN);
  assert.deepEqual(
    a.observations.map((o) => [o.monitor, o.observation.note]),
    [
      ["twice", "first"],
      ["twice", "second"],
    ],
  );
});

// A note for the reader rather than the runner: Observation has no verdict
// field, so a MonitoringPredicate cannot RETURN a verdict at all -- the
// substitution the falsifier names does not type-check. The tests above pin
// the half of the property the type system cannot: that the one bridge between
// the layers never lets a sighting decide anything.
```

