// THE ACCEPTANCE SPECIMEN (c60677), executable. Three named parts:
//
//   (a) the POSTCLOSE predicate a stranger can evaluate -- `proof-after-close`,
//       pure over (stored row, chain, T), and it never reads BROKEN: a proof
//       not submitted on time is DEFAULTED, which is a different accusation
//       from a commitment not met.
//   (b) one silence/break case that must default WITHOUT a late mark -- the
//       test below hands the evaluator a chain state no writer ever touched
//       (frozen, no disclosures key at all) and the default must come from the
//       read alone.
//   (c) the monitoring predicate interface is in monitor.ts; its half of the
//       specimen (monitoring output is never the late mark) is monitor.test.ts.
//
// The locked falsifier, from the same comment: a milestone whose acceptance
// tests pass a terminal DEFAULTED with no append-only late-evidence path, or
// that treats monitoring output as the late mark itself. The late-evidence
// test below is the first half; monitor.test.ts is the second.
//
// Killing mutations, each run before this was offered:
//   M1 drop `proof.at_time >= c.window.to` (early proof counts)  -> 1 test fails
//   M2 return BROKEN instead of DEFAULTED on missing proof       -> 5 tests fail
//   M3 default at T >= deadline instead of T > deadline          -> 1 test fails
//   M4 drop the late-proof evidence (bare DEFAULTED)             -> 1 test fails

import test from "node:test";
import assert from "node:assert/strict";
import { file, type ChainState, type Commitment } from "../src/commitment.ts";
import { evaluate, type LateProof } from "../src/evaluate.ts";

const SUBJ = "0x" + "aa".repeat(20);
const HOUR = 3_600_000;

const FROM = 1_000 * HOUR;
const TO = FROM + 24 * HOUR; // window: [FROM, TO)
const GRACE = 6;
const DEADLINE = TO + GRACE * HOUR;

function postclose(id = "pc-1"): Commitment {
  return {
    id,
    predicate: { kind: "proof-after-close", subject: SUBJ, token: null, grace_hours: GRACE },
    window: { from: FROM, to: TO },
  };
}

function chainWith(disclosures: ChainState["disclosures"]): ChainState {
  return { at_block: 10, at_time: DEADLINE + HOUR, transfers: [], balances: {}, disclosures };
}

// -- (a) the predicate, decided purely by (row, chain, T) --------------------

test("proof filed within grace reads HELD", () => {
  const r = evaluate(postclose(), chainWith({ "pc-1": { at_time: TO + HOUR } }), DEADLINE + HOUR);
  assert.equal(r.verdict, "HELD");
});

test("proof at exactly the deadline is on time; one ms past is not", () => {
  const atDeadline = evaluate(postclose(), chainWith({ "pc-1": { at_time: DEADLINE } }), DEADLINE + HOUR);
  assert.equal(atDeadline.verdict, "HELD");
  const past = evaluate(postclose(), chainWith({ "pc-1": { at_time: DEADLINE + 1 } }), DEADLINE + HOUR);
  assert.equal(past.verdict, "DEFAULTED");
});

test("a proof filed before the window closed is not a closing proof", () => {
  // The disclosure exists and is under the right id, but it predates TO: it
  // attests to a window that had not finished happening. (M1 kills this.)
  const r = evaluate(postclose(), chainWith({ "pc-1": { at_time: TO - 1 } }), DEADLINE + 1);
  assert.equal(r.verdict, "DEFAULTED");
  assert.match(r.reason, /predates/);
});

test("the grace is real: no proof yet reads HELD until the deadline passes", () => {
  const c = postclose();
  const chain = chainWith({});
  // Inside the window, inside the grace, and AT the deadline: all still HELD.
  // The default begins strictly after the deadline. (M3 kills this.)
  assert.equal(evaluate(c, chain, TO - 1).verdict, "HELD");
  assert.equal(evaluate(c, chain, TO + HOUR).verdict, "HELD");
  assert.equal(evaluate(c, chain, DEADLINE).verdict, "HELD");
  assert.equal(evaluate(c, chain, DEADLINE + 1).verdict, "DEFAULTED");
});

test("not-proved-on-time is DEFAULTED and never BROKEN, beside a true BROKEN on the same chain", () => {
  // One chain state, two commitments. The subject moved funds in-window
  // against a no-outbound promise (commitment not met -> BROKEN) and also
  // never filed the closing proof (proof not on time -> DEFAULTED). The
  // registry must keep the two accusations apart. (M2 kills this.)
  const chain: ChainState = {
    at_block: 10,
    at_time: DEADLINE + HOUR,
    balances: {},
    disclosures: {},
    transfers: [
      { tx: "0x" + "22".repeat(32), from: SUBJ, to: "0x" + "11".repeat(20), token: null, value: "1", at_block: 5, at_time: FROM + HOUR },
    ],
  };
  const noOut: Commitment = {
    id: "no-out-1",
    predicate: { kind: "no-outbound-transfer", subject: SUBJ, token: null },
    window: { from: FROM, to: TO },
  };
  assert.equal(evaluate(noOut, chain, DEADLINE + HOUR).verdict, "BROKEN");
  assert.equal(evaluate(postclose(), chain, DEADLINE + HOUR).verdict, "DEFAULTED");
});

// -- (b) the silence case: default with no late mark anywhere ----------------

test("SILENCE: every writer dead since before the close, and the read still defaults", () => {
  // No disclosures key at all -- this chain state was never touched by any
  // writer that could have marked anything, and it is frozen so the evaluator
  // cannot write a late mark even by accident. The DEFAULTED must come from
  // (row, chain, T) alone. (M4's cousin: reading absent disclosures as a
  // present proof, or crashing on the missing key, kills this.)
  const chain: ChainState = Object.freeze({
    at_block: 10,
    at_time: DEADLINE + HOUR,
    transfers: Object.freeze([]) as unknown as ChainState["transfers"],
    balances: Object.freeze({}),
  });
  const c = Object.freeze(postclose());
  const r = evaluate(c as Commitment, chain as ChainState, DEADLINE + 1);
  assert.equal(r.verdict, "DEFAULTED");
  assert.equal(r.reason, "no closing proof within grace");
});

// -- the append-only late-evidence path ---------------------------------------

test("a late proof never lifts the default, and is carried as evidence beside it", () => {
  const late = TO + (GRACE + 2) * HOUR;
  const r = evaluate(postclose(), chainWith({ "pc-1": { at_time: late } }), late + 1);
  assert.equal(r.verdict, "DEFAULTED"); // terminal: on-time was the promise
  const ev = r.evidence as LateProof;
  assert.ok(ev, "the late arrival must be appended as evidence, not dropped"); // (M4 kills this)
  assert.equal(ev.proof_at, late);
  assert.equal(ev.deadline, DEADLINE);
});

// -- the filing gate ----------------------------------------------------------

test("the gate can witness a POSTCLOSE break: silence past the deadline", () => {
  const filed = file(postclose());
  assert.ok(filed.filed, "proof-after-close must be filable: it can fail");
  if (filed.filed) {
