    // failing verdict. (Same contract the disclosed-within witness already
    // relies on: the gate's question is "show me the state that fails you".)
    const r = evaluate(postclose(), filed.witness, filed.witness.at_time);
    assert.equal(r.verdict, "DEFAULTED");
  }
});

test("the gate refuses a grace that is not a number of hours", () => {
  for (const grace_hours of [Number.NaN, Number.POSITIVE_INFINITY, -1]) {
    const r = file({
      id: "bad",
      predicate: { kind: "proof-after-close", subject: SUBJ, token: null, grace_hours },
      window: { from: FROM, to: TO },
    });
    assert.equal(r.filed, false);
  }
});
