          return {
            verdict: "DEFAULTED",
            reason: "closing proof arrived after the grace deadline",
            evidence: { commitment: c.id, proof_at: late.at_time, deadline },
          };
        }
        if (proofs.length) {
          return { verdict: "DEFAULTED", reason: "only proof under this id predates the window close" };
        }
        return { verdict: "DEFAULTED", reason: "no closing proof within grace" };
